package main

import "time"

func worker(work <-chan int) {
	t := time.NewTimer(time.Minute)
	defer t.Stop()
	for {
		select {
		case w := <-work:
			_ = w
			if !t.Stop() {
				<-t.C // слить сработавший таймер (до Go 1.23)
			}
			t.Reset(time.Minute)
		case <-t.C:
			return
		}
	}
}

func main() {
	ch := make(chan int)
	close(ch)
	worker(ch)
}

