package main

import (
	"context"
	"time"
)

type Stream interface {
	Send(v int) error
	Context() context.Context
}

func produce(ctx context.Context, ch chan<- int) {
	for i := 0; ; i++ {
		select {
		case <-ctx.Done():
			return // клиент ушёл — выходим
		case ch <- i:
			time.Sleep(time.Millisecond)
		}
	}
}

func Subscribe(stream Stream) error {
	ctx := stream.Context()
	updates := make(chan int)
	go produce(ctx, updates)
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case u := <-updates:
			if err := stream.Send(u); err != nil {
				return err
			}
		}
	}
}

func main() { _ = Subscribe }

